entry:
\forall Heap h; \forall Object o; \forall Field f;
   ( elementOf<Loc>(pair<Object,Field>(o,f),freshLocs(h))<<Trigger>> <->
      o != null & !select<boolean>(h,o,java.lang.Object::#$created)=TRUE )

\forall Object o; \forall Field f; \forall Object o2;
  ( elementOf<Loc>(pair<Object,Field>(o,f), allFields(o2))<<Trigger>> <->
     o = o2 )

\forall Object o; \forall Object o2; \forall Field f; \forall int lo; \forall int hi;
  (elementOf<Loc>(pair<Object,Field>(o,f), arrayRange(o2, lo, hi))<<Trigger>> <->
    o = o2 & \exists int iv; (f = arr(iv) & lo <= iv & iv <= hi))
